referenceSolutions.javascript:
export function solve(limit, window, times) {
  const accepted = [];
  return times.map((time) => {
    while (accepted.length && accepted[0] <= time - window) accepted.shift();
    if (accepted.length >= limit) return false;
    accepted.push(time);
    return true;
  });
}

